export type IpcArgumentKind = "string" | "number" | "boolean" | "record" | "array" | "unknown" | "optional-string" | "optional-number" | "optional-boolean" | "optional-record" | "optional-array" | "optional-unknown";

export interface IpcEndpointContract {
  readonly arguments: readonly IpcArgumentKind[];
  readonly outputType: string;
  readonly outputSchema: "structured-clone-value";
  readonly rejectsAbsoluteRendererPaths: boolean;
  readonly behaviorTest: string;
}

function endpoint<const TArguments extends readonly IpcArgumentKind[]>(contract: Omit<IpcEndpointContract, "arguments"> & { readonly arguments: TArguments }): IpcEndpointContract {
  return Object.freeze({ ...contract, arguments: Object.freeze([...contract.arguments]) });
}

